const POSTS_PER_PAGE = 10

const PostList = ({ postList }) => {
  const [currentPage, setCurrentPage] = useState(1)
  
  const totalPages = Math.ceil(postList.length / POSTS_PER_PAGE)
  const startIndex = (currentPage - 1) * POSTS_PER_PAGE
  const endIndex = startIndex + POSTS_PER_PAGE
  const currentPosts = postList.slice(startIndex, endIndex)

  const handlePageChange = (page) => {
    setCurrentPage(page)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const handlePrevPage = () => {
    if (currentPage > 1) {
      handlePageChange(currentPage - 1)
    }
  }

  const handleNextPage = () => {
    if (currentPage < totalPages) {
      handlePageChange(currentPage + 1)
    }
  }

  // 페이지 번호 배열 생성 (최대 5개 페이지 표시)
  const getPageNumbers = () => {
    const pages = []
    const maxVisiblePages = 5
    
    if (totalPages <= maxVisiblePages) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i)
      }
    } else {
      if (currentPage <= 3) {
        for (let i = 1; i <= 5; i++) {
          pages.push(i)
        }
      } else if (currentPage >= totalPages - 2) {
        for (let i = totalPages - 4; i <= totalPages; i++) {
          pages.push(i)
        }
      } else {
        for (let i = currentPage - 2; i <= currentPage + 2; i++) {
          pages.push(i)
        }
      }
    }
    
    return pages
  }

  useEffect(() => {
    setCurrentPage(1)
  }, [postList])

  return (
    <>
      <PostCount>
        총 <strong>{postList.length}</strong>개의 포스트 중 <strong>{startIndex + 1}-{Math.min(endIndex, postList.length)}</strong>번째 포스트
      </PostCount>
      
      <PostListWrapper>
        {currentPosts.map((post, i) => {
          const { title, date, tags } = post.frontmatter
          const { excerpt } = post
          const { slug } = post.fields

          return (
            <PostWrapper key={JSON.stringify({ slug, date })}>
              <PostLink to={slug}>
                <PostHeader>
                  <Date dateTime={date}>{date}</Date>
                  <PostTitle>{title}</PostTitle>
                </PostHeader>
                
                <PostContent>
                  <Excerpt>{excerpt}</Excerpt>
                </PostContent>
                
                <PostFooter>
                  <TagList tagList={tags} />
                  <ReadMoreIndicator>
                    더 읽기
                  </ReadMoreIndicator>
                </PostFooter>
              </PostLink>
            </PostWrapper>
          )
        })}
      </PostListWrapper>
      
      {totalPages > 1 && (
        <PaginationWrapper>
          <PaginationButton 
            onClick={handlePrevPage}
            disabled={currentPage === 1}
          >
            <FaChevronLeft />
          </PaginationButton>
          
          {getPageNumbers().map(page => (
            <PaginationButton
              key={page}
              active={page === currentPage}
              onClick={() => handlePageChange(page)}
            >
              {page}
            </PaginationButton>
          ))}
          
          <PaginationButton 
            onClick={handleNextPage}
            disabled={currentPage === totalPages}
          >
            <FaChevronRight />
          </PaginationButton>
          
          <PageInfo>
            {currentPage} / {totalPages} 페이지
          </PageInfo>
        </PaginationWrapper>
      )}
    </>
  )
}

export default PostList
